#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> adj(N + 1);

    for (int i = 0; i < N - 1; i++) {
        int A, B;
        cin >> A >> B;
        adj[A].push_back(B);
        adj[B].push_back(A);
    }

    vector<int> parent(N + 1, 0);
    vector<int> order;
    order.reserve(N);

    vector<int> st;
    st.push_back(1);
    parent[1] = -1;

    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        order.push_back(v);

        for (int u : adj[v]) {
            if (u == parent[v]) continue;
            parent[u] = v;
            st.push_back(u);
        }
    }

    vector<int> sz(N + 1, 1);

    for (int i = N - 1; i >= 0; i--) {
        int v = order[i];
        if (parent[v] > 0) {
            sz[parent[v]] += sz[v];
        }
    }

    int ans = N;

    for (int v = 2; v <= N; v++) {
        int diff = abs(N - 2 * sz[v]);
        if (diff < ans) ans = diff;
    }

    cout << ans << '\n';

    return 0;
}
